mapper.select:
/* WebLeavePromo01Mapper.selectDesignateTargets */ WITH RECURSIVE node_tree AS ( SELECT N.CMPNY_CD , N.SITE_CD , N.NODE_CD , N.NODE_NM FROM TB_SITE_NODE N WHERE N.CMPNY_CD = #{gvCmpnyCd} AND N.SITE_CD = #{siteCd}
AND N.NODE_CD = #{nodeCd}
AND N.PARENT_NODE_CD IS NULL
UNION ALL
SELECT C.CMPNY_CD , C.SITE_CD , C.NODE_CD , C.NODE_NM FROM TB_SITE_NODE C INNER JOIN node_tree P ON C.CMPNY_CD = P.CMPNY_CD AND C.SITE_CD = P.SITE_CD AND C.PARENT_NODE_CD = P.NODE_CD
)
SELECT U.USER_CD AS userCd , U.USER_NM AS userNm , NT.NODE_NM AS nodeNm , S.SITE_NM AS siteNm , U.HIRE_DATE AS hireDate , IFNULL(REM.REMAINING_DAYS, 0) AS unusedDays , IFNULL(M.STAGE2_TARGET_DAYS, 0) AS stage2TargetDays , M.BASE_AVAIL_TO_DATE AS baseAvailToDate FROM TB_USER U INNER JOIN node_tree NT ON U.CMPNY_CD = NT.CMPNY_CD AND U.SITE_CD = NT.SITE_CD AND U.NODE_CD = NT.NODE_CD INNER JOIN TB_SITE S ON S.CMPNY_CD = U.CMPNY_CD AND S.SITE_CD = U.SITE_CD INNER JOIN TB_LEAVE_POLICY P ON P.CMPNY_CD = U.CMPNY_CD AND P.USE_YN = 'Y' AND P.AXIS7_USE_PROMOTION = 'Y' INNER JOIN ( /* SECOND 회차 마스터(스코프 내 2차 도래자) — 가장 임박 만료일 1건 */ SELECT M1.CMPNY_CD , M1.USER_CD , M1.BASE_AVAIL_TO_DATE , M1.STAGE2_TARGET_DAYS FROM TB_LEAVE_PROMOTION_LOG M1 WHERE M1.CMPNY_CD = #{gvCmpnyCd} AND M1.PROMO_STAGE = 'SECOND' AND M1.STATUS IN ('NOTICED', 'DESIGNATED') AND M1.DEL_YN = 'N' AND NOT EXISTS ( SELECT 1 FROM TB_LEAVE_PROMOTION_LOG M2 WHERE M2.CMPNY_CD = M1.CMPNY_CD AND M2.USER_CD = M1.USER_CD AND M2.PROMO_STAGE = 'SECOND' AND M2.STATUS IN ('NOTICED', 'DESIGNATED') AND M2.DEL_YN = 'N' AND ( M2.BASE_AVAIL_TO_DATE < M1.BASE_AVAIL_TO_DATE OR (M2.BASE_AVAIL_TO_DATE = M1.BASE_AVAIL_TO_DATE AND M2.PROMO_ID < M1.PROMO_ID) ) ) ) M ON M.CMPNY_CD = U.CMPNY_CD AND M.USER_CD = U.USER_CD LEFT JOIN ( /* 본연차+근속가산 ACTIVE 미사용 잔여 합(미래 등록분=USED_DAYS 반영) */ SELECT R.CMPNY_CD , R.USER_CD , SUM(R.GRANT_DAYS - R.USED_DAYS) AS REMAINING_DAYS FROM TB_USER_LEAVE_GRANT R WHERE R.GRANT_TYPE IN ('STATUTORY_ANNUAL', 'STATUTORY_TENURE_BONUS') AND R.STATUS = 'ACTIVE' AND R.DEL_YN = 'N' GROUP BY R.CMPNY_CD, R.USER_CD ) REM ON REM.CMPNY_CD = U.CMPNY_CD AND REM.USER_CD = U.USER_CD WHERE U.CMPNY_CD = #{gvCmpnyCd} AND U.SITE_CD = #{siteCd} AND U.USE_YN = 'Y' AND U.ACCOUNT_STATUS = '01' AND IFNULL(REM.REMAINING_DAYS, 0) > 0
AND U.USER_NM LIKE CONCAT('%', #{userNm}, '%')
AND U.HIRE_DATE IS NOT NULL AND U.HIRE_DATE <= #{oneYearAgoYmd}
AND (U.HIRE_DATE IS NULL OR U.HIRE_DATE > #{oneYearAgoYmd})
ORDER BY U.USER_NM ASC, U.USER_CD ASC

/* WebLeavePromo01Mapper.selectFirstTargets */ WITH RECURSIVE node_tree AS ( SELECT N.CMPNY_CD , N.SITE_CD , N.NODE_CD , N.NODE_NM FROM TB_SITE_NODE N WHERE N.CMPNY_CD = #{gvCmpnyCd} AND N.SITE_CD = #{siteCd}
AND N.NODE_CD = #{nodeCd}
AND N.PARENT_NODE_CD IS NULL
UNION ALL
SELECT C.CMPNY_CD , C.SITE_CD , C.NODE_CD , C.NODE_NM FROM TB_SITE_NODE C INNER JOIN node_tree P ON C.CMPNY_CD = P.CMPNY_CD AND C.SITE_CD = P.SITE_CD AND C.PARENT_NODE_CD = P.NODE_CD
)
SELECT U.USER_CD AS userCd , U.USER_NM AS userNm , U.NODE_CD AS nodeCd , NT.NODE_NM AS nodeNm , U.SITE_CD AS siteCd , S.SITE_NM AS siteNm , M.NOTICED_DATE AS noticedDate , M.BASE_AVAIL_TO_DATE AS baseAvailToDate , IFNULL(M.STAGE1_DESIGNATED_DAYS, 0) AS stage1DesignatedDays , M.LOGIN_NOTIFIED_YN AS loginNotifiedYn , SUB.FIRST_SUBMIT_DATE AS firstSubmitDateRaw , IFNULL(RM.REMIND_CNT, 0) AS remindCntRaw , RM.LAST_REMIND_DATE AS lastRemindDateRaw FROM TB_USER U INNER JOIN node_tree NT ON U.CMPNY_CD = NT.CMPNY_CD AND U.SITE_CD = NT.SITE_CD AND U.NODE_CD = NT.NODE_CD INNER JOIN TB_SITE S ON S.CMPNY_CD = U.CMPNY_CD AND S.SITE_CD = U.SITE_CD INNER JOIN TB_LEAVE_POLICY P ON P.CMPNY_CD = U.CMPNY_CD AND P.USE_YN = 'Y' AND P.AXIS7_USE_PROMOTION = 'Y' INNER JOIN ( /* FIRST 회차 마스터 — 가장 임박한 만료일 1건(STATUS 무필터, DEL_YN 만 적용) */ SELECT M1.CMPNY_CD , M1.USER_CD , M1.BASE_AVAIL_TO_DATE , M1.NOTICED_DATE , M1.STAGE1_DESIGNATED_DAYS , M1.LOGIN_NOTIFIED_YN FROM TB_LEAVE_PROMOTION_LOG M1 WHERE M1.CMPNY_CD = #{gvCmpnyCd} AND M1.PROMO_STAGE = 'FIRST' AND M1.DEL_YN = 'N' AND NOT EXISTS ( SELECT 1 FROM TB_LEAVE_PROMOTION_LOG M2 WHERE M2.CMPNY_CD = M1.CMPNY_CD AND M2.USER_CD = M1.USER_CD AND M2.PROMO_STAGE = 'FIRST' AND M2.DEL_YN = 'N' AND ( M2.BASE_AVAIL_TO_DATE < M1.BASE_AVAIL_TO_DATE OR (M2.BASE_AVAIL_TO_DATE = M1.BASE_AVAIL_TO_DATE AND M2.PROMO_ID < M1.PROMO_ID) ) ) ) M ON M.CMPNY_CD = U.CMPNY_CD AND M.USER_CD = U.USER_CD LEFT JOIN ( /* 1차 촉진 연차 최초 등록일(제출 시점 판정). GRANT_ID 로 회차를 스코프하지 않는다 — 차감 grant 는 만료 임박순으로 선택되므로 근속가산 grant 가 선택될 수 있어 마스터 BASE_GRANT_ID 와 불일치할 수 있다. 회차 스코프는 서비스가 통지일 기준(등록일이 통지일 미만이면 이전 회차분)으로 적용한다. */ SELECT LU.CMPNY_CD , LU.USER_CD , DATE_FORMAT(MIN(LU.INSERT_DATE), '%Y%m%d') AS FIRST_SUBMIT_DATE FROM TB_USER_LEAVE_USE LU WHERE LU.CMPNY_CD = #{gvCmpnyCd} AND LU.LEAVE_CD = 'SYS_ANNUAL' AND LU.LEAVE_STATUS = 'CONFIRMED' AND LU.DEL_YN = 'N' AND LU.PROMOTION_STAGE = 'FIRST' GROUP BY LU.CMPNY_CD, LU.USER_CD ) SUB ON SUB.CMPNY_CD = U.CMPNY_CD AND SUB.USER_CD = U.USER_CD LEFT JOIN ( /* 독촉(재안내) 발송 이력 집계. NOTI_TYPE 문자열은 LeavePromotionNotiConst.NOTI_TYPE_PROMOTION_REMIND / SYS045 시드와 동일해야 한다. 회차 스코프도 서비스가 통지일 기준으로 적용한다. */ SELECT NO2.CMPNY_CD , NO2.TARGET_USER_CD , COUNT(1) AS REMIND_CNT , DATE_FORMAT(MAX(NO2.INSERT_DATE), '%Y%m%d') AS LAST_REMIND_DATE FROM TB_NOTI_OUTBOX NO2 WHERE NO2.CMPNY_CD = #{gvCmpnyCd} AND NO2.NOTI_TYPE = 'LEAVE_PROMOTION_REMIND' AND NO2.DEL_YN = 'N' GROUP BY NO2.CMPNY_CD, NO2.TARGET_USER_CD ) RM ON RM.CMPNY_CD = U.CMPNY_CD AND RM.TARGET_USER_CD = U.USER_CD WHERE U.CMPNY_CD = #{gvCmpnyCd} AND U.SITE_CD = #{siteCd} AND U.USE_YN = 'Y' AND U.ACCOUNT_STATUS = '01'
AND U.USER_NM LIKE CONCAT('%', #{userNm}, '%')
ORDER BY U.USER_NM ASC, U.USER_CD ASC

/* WebLeavePromo01Mapper.countRemindToday */
SELECT COUNT(1)
  FROM TB_NOTI_OUTBOX
 WHERE CMPNY_CD  = #{cmpnyCd}
   AND DEDUP_KEY = #{dedupKey}
   AND DEL_YN    = 'N'
